arguments.command:
cd /workspace && python3 -c "
import sys; sys.path.insert(0,'/workspace/project')
from syntax import parse, PolicyError
print(parse('((match(A) or match(B)) and startswith(C)) allow;'))
print(parse('contains() allow;'))
print(parse('startswith(A,B,C,D) allow;'))
try: parse('startswith(A,B,C,D,E) allow;')
except PolicyError as e: print('ok nonmatch path:', e)
try: parse('match(' + 'A,'*16 + 'A) allow;')
except PolicyError as e: print('ok path 17:', e)
print(parse('match(' + 'A,'*15 + 'A) allow;'))
# depth: 16 nested nots ok, 17 fails
p16 = 'not('*15 + 'match(A)' + ')'*15
print(parse(p16 + ' allow;')[1])
p17 = 'not('*16 + 'match(A)' + ')'*16
try: parse(p17 + ' allow;')
except PolicyError as e: print('ok depth:', e)
# keywords as names
print(parse('match(match,and,or,not,allow,drop) allow;'))
# complex rule budget
rules = ' '.join('contains(A) allow;' for _ in range(8))
print(parse(rules)[1:3])
rules9 = ' '.join('contains(A) allow;' for _ in range(9))
try: parse(rules9)
except PolicyError as e: print('ok complex:', e)
# distinct nonmatch
try: parse('contains(A) allow; endswith(B) allow; startswith(C) allow; match(A) allow; contains(A,B) allow;')
except PolicyError as e: print('ok distinct:', e)
# empty-path atoms
print(parse('endswith() allow;')[0])
"
